parameters.jsonBody:
={
  "model": "claude-opus-4-6",
  "max_tokens": 1024,
  "messages": [
    {
      "role": "user",
      "content": "You are a senior SRE. Analyze this incident alert and provide:
1. Root cause hypothesis (2-3 sentences)
2. Immediate actions (3 bullet points)
3. Severity assessment (P1/P2/P3/P4)
4. Estimated resolution time

Alert Details:
Title: {{ $json.alert_title }}
Severity: {{ $json.alert_severity }}
Service: {{ $json.alert_service }}
Message: {{ $json.alert_message }}
Timestamp: {{ $json.alert_timestamp }}

Respond in this exact JSON format:
{"hypothesis": "", "actions": [], "severity": "", "eta": ""}"
    }
  ]
}

={
  "text": "🚨 *Incident Alert: {{ $('Normalize Alert Fields').item.json.alert_title }}*",
  "blocks": [
    {
      "type": "header",
      "text": { "type": "plain_text", "text": "🚨 Incident Alert Enriched by AI" }
    },
    {
      "type": "section",
      "fields": [
        { "type": "mrkdwn", "text": "*Service:*\n{{ $('Normalize Alert Fields').item.json.alert_service }}" },
        { "type": "mrkdwn", "text": "*Severity:*\n{{ $json.ai_analysis.severity || $('Normalize Alert Fields').item.json.alert_severity }}" },
        { "type": "mrkdwn", "text": "*ETA to Resolve:*\n{{ $json.ai_analysis.eta }}" },
        { "type": "mrkdwn", "text": "*Time:*\n{{ $('Normalize Alert Fields').item.json.alert_timestamp }}" }
      ]
    },
    {
      "type": "section",
      "text": { "type": "mrkdwn", "text": "*Root Cause Hypothesis:*\n{{ $json.ai_analysis.hypothesis }}" }
    },
    {
      "type": "section",
      "text": { "type": "mrkdwn", "text": "*Immediate Actions:*\n• {{ $json.ai_analysis.actions.join('\n• ') }}" }
    }
  ]
}
